const hashIndex = (s: string, max: number): number => {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (h * 31 + s.charCodeAt(i)) & 0xffffffff;
  }
  return Math.abs(h) % max;
};

export const img = (prompt: string, size: string = "landscape_4_3") => {
  const words = prompt.toLowerCase().split(/[\s,_-]+/);
  let category = words.find((w) => w in CATEGORY_IMAGES) || "walk";

  if (!(category in CATEGORY_IMAGES)) {
    category = "walk";
  }

  const images = CATEGORY_IMAGES[category];
  const index = hashIndex(prompt, images.length);
  return images[index];
};

