import type { DayPart } from "@/types/activity";

export interface Greeting {
  part: DayPart;
  partLabel: string; // "清晨" / "黄昏" 等
  line: string; // 一句温柔的开场白
  sub: string; // 小字副标题
}

// 根据小时数返回时段
export function getDayPart(date: Date = new Date()): DayPart {
  const h = date.getHours();
  if (h >= 5 && h < 10) return "morning";
  if (h >= 10 && h < 14) return "noon";
  if (h >= 14 && h < 17) return "afternoon";
  if (h >= 17 && h < 19) return "dusk";
  return "night";
}

const GREETINGS: Record<DayPart, Omit<Greeting, "part">> = {
  morning: {
    partLabel: "清晨",
    line: "早啊，今天先别急着忙。",
    sub: "属于你的、还没被切走的一个小时",
  },
  noon: {
    partLabel: "午间",
    line: "午休多出来的一小时，别还给工位。",
    sub: "找一个能让你坐下来的地方",
  },
  afternoon: {
    partLabel: "午后",
    line: "下午的光，最适合出去走一段。",
    sub: "不看攻略，只看此刻能去哪",
  },
  dusk: {
    partLabel: "黄昏",
    line: "黄昏了，要不要不直接回家。",
    sub: "把今天的余响，走掉一点",
  },
  night: {
    partLabel: "夜晚",
    line: "夜还没尽，一个人也可以出去。",
    sub: "看一场电影，或翻一本书",
  },
};

export function getGreeting(date: Date = new Date()): Greeting {
  const part = getDayPart(date);
  return { part, ...GREETINGS[part] };
}

// 格式化当前日期：7 月 5 日 周六
export function formatDate(date: Date = new Date()): string {
  const weekdays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  return `${date.getMonth() + 1} 月 ${date.getDate()} 日 ${weekdays[date.getDay()]}`;
}

// 格式化当前时间：14:32
export function formatTime(date: Date = new Date()): string {
  const h = String(date.getHours()).padStart(2, "0");
  const m = String(date.getMinutes()).padStart(2, "0");
  return `${h}:${m}`;
}
