import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { Category, ShareRecord } from "@/types/activity";
import { REGIONS } from "@/types/activity";

export interface UserInfo {
  nickname: string;
  avatar: string; // 单字头像
}

interface UserState {
  isLoggedIn: boolean;
  user: UserInfo | null;
  favorites: string[];
  footprint: string[];
  shares: ShareRecord[]; // 当前用户发布的分享
  preferences: {
    categories: Category[];
    regions: string[];
  };
  onboarded: boolean;

  // actions
  login: (info?: Partial<UserInfo>) => void;
  logout: () => void;
  toggleFavorite: (id: string) => void;
  isFavorite: (id: string) => boolean;
  removeFavorite: (id: string) => void; // 从收藏中删除（用于失效清理）
  toggleFootprint: (id: string) => void;
  isVisited: (id: string) => boolean;
  addShare: (share: ShareRecord) => void;
  removeShare: (id: string) => void;
  toggleCategory: (c: Category) => void;
  toggleRegion: (r: string) => void;
  setOnboarded: (v: boolean) => void;
  resetAll: () => void;
}

export const useUserStore = create<UserState>()(
  persist(
    (set, get) => ({
      isLoggedIn: false,
      user: null,
      favorites: [],
      footprint: [],
      shares: [],
      preferences: {
        categories: [],
        regions: [],
      },
      onboarded: false,

      // 模拟微信登录：demo 中点击即登录
      login: (info) =>
        set({
          isLoggedIn: true,
          user: {
            nickname: info?.nickname ?? "觅友",
            avatar: info?.avatar ?? "觅",
          },
        }),
      logout: () => set({ isLoggedIn: false, user: null }),

      toggleFavorite: (id) =>
        set((s) => ({
          favorites: s.favorites.includes(id)
            ? s.favorites.filter((f) => f !== id)
            : [id, ...s.favorites],
        })),
      isFavorite: (id) => get().favorites.includes(id),
      removeFavorite: (id) =>
        set((s) => ({ favorites: s.favorites.filter((f) => f !== id) })),

      toggleFootprint: (id) =>
        set((s) => ({
          footprint: s.footprint.includes(id)
            ? s.footprint.filter((f) => f !== id)
            : [id, ...s.footprint],
        })),
      isVisited: (id) => get().footprint.includes(id),

      addShare: (share) =>
        set((s) => ({ shares: [share, ...s.shares] })),
      removeShare: (id) =>
        set((s) => ({ shares: s.shares.filter((x) => x.id !== id) })),

      toggleCategory: (c) =>
        set((s) => ({
          preferences: {
            ...s.preferences,
            categories: s.preferences.categories.includes(c)
              ? s.preferences.categories.filter((x) => x !== c)
              : [...s.preferences.categories, c],
          },
        })),
      toggleRegion: (r) =>
        set((s) => ({
          preferences: {
            ...s.preferences,
            regions: s.preferences.regions.includes(r)
              ? s.preferences.regions.filter((x) => x !== r)
              : [...s.preferences.regions, r],
          },
        })),
      setOnboarded: (v) => set({ onboarded: v }),
      resetAll: () =>
        set({
          isLoggedIn: false,
          user: null,
          favorites: [],
          footprint: [],
          shares: [],
          preferences: { categories: [], regions: [] },
          onboarded: false,
        }),
    }),
    {
      name: "mi-user-state",
      version: 1,
      partialize: (s) => ({
        isLoggedIn: s.isLoggedIn,
        user: s.user,
        favorites: s.favorites,
        footprint: s.footprint,
        shares: s.shares,
        preferences: s.preferences,
        onboarded: s.onboarded,
      }),
    },
  ),
);

export { REGIONS };
