import { lazy, Suspense } from "react";
import { HashRouter as Router, Routes, Route, useLocation, Navigate, useNavigate } from "react-router-dom";
import { AnimatePresence } from "framer-motion";
import PhoneFrame from "@/components/PhoneFrame";
import { useUserStore } from "@/store/useUserStore";
import { ArrowLeft } from "lucide-react";

// 路由组件懒加载，实现代码分割
const Discover = lazy(() => import("@/pages/Discover"));
const Detail = lazy(() => import("@/pages/Detail"));
const Favorites = lazy(() => import("@/pages/Favorites"));
const Share = lazy(() => import("@/pages/Share"));
const Profile = lazy(() => import("@/pages/Profile"));
const Preferences = lazy(() => import("@/pages/Preferences"));
const Onboarding = lazy(() => import("@/pages/Onboarding"));
const Login = lazy(() => import("@/pages/Login"));
const Settings = lazy(() => import("@/pages/Settings"));

// 登录守卫：未登录跳转登录页
function RequireAuth({ children }: { children: React.ReactNode }) {
  const location = useLocation();
  const isLoggedIn = useUserStore((s) => s.isLoggedIn);
  if (!isLoggedIn) {
    return <Navigate to="/login" state={{ from: location.pathname }} replace />;
  }
  return <>{children}</>;
}

// 404 页面
function NotFound() {
  const navigate = useNavigate();
  return (
    <div className="flex-1 flex flex-col items-center justify-center gap-4 p-8 text-center">
      <p className="font-display text-4xl text-tea/40">404</p>
      <p className="font-serif text-tea">这一页似乎走丢了。</p>
      <button
        onClick={() => navigate("/")}
        className="flex items-center gap-1.5 text-sm text-cinnabar underline underline-offset-4"
      >
        <ArrowLeft size={14} strokeWidth={1.5} />
        回到推荐
      </button>
    </div>
  );
}

function AnimatedRoutes() {
  const location = useLocation();
  const onboarded = useUserStore((s) => s.onboarded);

  // 全局引导守卫：未完成引导时，除引导页和登录页外都重定向
  if (!onboarded && location.pathname !== "/onboarding" && location.pathname !== "/login") {
    return (
      <AnimatePresence mode="wait">
        <Navigate to="/onboarding" replace />
      </AnimatePresence>
    );
  }

  return (
    <Suspense fallback={null}>
      <AnimatePresence mode="wait">
        <Routes location={location} key={location.pathname}>
          <Route path="/" element={<Discover />} />
          <Route path="/detail/:id" element={<Detail />} />
          <Route path="/favorites" element={<RequireAuth><Favorites /></RequireAuth>} />
          <Route path="/share" element={<RequireAuth><Share /></RequireAuth>} />
          <Route path="/profile" element={<RequireAuth><Profile /></RequireAuth>} />
          <Route path="/profile/preferences" element={<RequireAuth><Preferences /></RequireAuth>} />
          <Route path="/profile/settings" element={<RequireAuth><Settings /></RequireAuth>} />
          <Route path="/onboarding" element={<Onboarding />} />
          <Route path="/login" element={<Login />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </AnimatePresence>
    </Suspense>
  );
}

export default function App() {
  return (
    <Router>
      <PhoneFrame>
        <AnimatedRoutes />
      </PhoneFrame>
    </Router>
  );
}
