import { useLocation, useNavigate } from "react-router-dom";
import { Compass, Heart, Feather, User } from "lucide-react";
import { useUserStore } from "@/store/useUserStore";

// 底部 Tab：发现 / 收藏 / 分享 / 我的
export default function TabBar() {
  const navigate = useNavigate();
  const location = useLocation();
  const { isLoggedIn } = useUserStore();

  const tabs = [
    { key: "discover", label: "发现", icon: Compass, path: "/", needAuth: false },
    { key: "favorites", label: "收藏", icon: Heart, path: "/favorites", needAuth: true },
    { key: "share", label: "分享", icon: Feather, path: "/share", needAuth: true },
    { key: "profile", label: "我的", icon: User, path: "/profile", needAuth: true },
  ];

  const isActive = (path: string) => {
    if (path === "/") return location.pathname === "/";
    return location.pathname.startsWith(path);
  };

  const handleClick = (path: string, needAuth: boolean) => {
    // 需要登录的页面：未登录时跳转登录页，并带上来源
    if (needAuth && !isLoggedIn) {
      navigate("/login", { state: { from: path } });
      return;
    }
    navigate(path);
  };

  return (
    <nav className="absolute bottom-0 left-0 right-0 z-30 border-t border-line/70 bg-paper/90 backdrop-blur-md">
      <div className="flex">
        {tabs.map((t) => {
          const active = isActive(t.path);
          const Icon = t.icon;
          return (
            <button
              key={t.key}
              onClick={() => handleClick(t.path, t.needAuth)}
              className="flex-1 flex flex-col items-center gap-1 py-2.5 transition-colors"
            >
              <Icon
                size={18}
                strokeWidth={1.5}
                className={active ? "text-cinnabar" : "text-ink/40"}
              />
              <span
                className={`text-[10px] tracking-wider ${
                  active ? "text-cinnabar font-medium" : "text-ink/40"
                }`}
              >
                {t.label}
              </span>
            </button>
          );
        })}
      </div>
      {/* iOS home indicator 模拟 */}
      <div className="flex justify-center pb-1.5">
        <div className="w-28 h-1 rounded-full bg-ink/20" />
      </div>
    </nav>
  );
}
