import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import { Clock, MapPin, Train, Wallet } from "lucide-react";
import type { Activity } from "@/types/activity";
import { CATEGORY_LABEL, formatDuration } from "@/types/activity";

interface Props {
  activity: Activity;
  index?: number;
}

export default function ActivityCard({ activity, index = 0 }: Props) {
  const navigate = useNavigate();

  return (
    <motion.button
      layoutId={`card-${activity.id}`}
      onClick={() => navigate(`/detail/${activity.id}`)}
      initial={{ opacity: 0, y: 16 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
      transition={{
        duration: 0.5,
        delay: Math.min(index * 0.06, 0.4),
        ease: [0.22, 1, 0.36, 1],
      }}
      className="block w-full text-left bg-cream rounded-card border border-line overflow-hidden shadow-paper hover:shadow-card hover:border-tea/30 transition-all group"
    >
      {/* 封面图 */}
      <motion.div layoutId={`cover-${activity.id}`} className="relative aspect-[3/2] overflow-hidden bg-line/40">
        <img
          src={activity.cover}
          alt={activity.name}
          loading="lazy"
          className="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-700"
        />
        {/* 类别小标 */}
        <div className="absolute top-3 left-3">
          <span className="px-2.5 py-1 rounded-full bg-paper/85 backdrop-blur-sm text-[10px] text-ink tracking-wider">
            {CATEGORY_LABEL[activity.category]}
          </span>
        </div>
        {/* 单人友好标记 */}
        {activity.soloFriendly === 3 && (
          <div className="absolute top-3 right-3">
            <span className="px-2.5 py-1 rounded-full bg-cinnabar/80 backdrop-blur-sm text-[10px] text-cream tracking-wider">
              单人友好
            </span>
          </div>
        )}
      </motion.div>

      {/* 文案区：加大内边距，丰富内容 */}
      <div className="p-6">
        <motion.h3
          layoutId={`name-${activity.id}`}
          className="font-serif text-lg text-ink tracking-tight-display"
        >
          {activity.name}
        </motion.h3>
        <p className="mt-2 font-serif text-[14px] text-tea leading-relaxed line-clamp-2">
          {activity.oneLiner}
        </p>

        {/* 氛围标签 */}
        <div className="mt-3 flex flex-wrap gap-1.5">
          {activity.tags.slice(0, 3).map((t) => (
            <span
              key={t}
              className="px-2 py-0.5 rounded-full text-[10px] text-tea/70 bg-paper border border-line/60"
            >
              {t}
            </span>
          ))}
        </div>

        {/* 元信息：路程时长 + 活动时长 + 区域 + 价格 */}
        <div className="mt-4 space-y-2.5">
          {/* 时长行：路程 + 活动 */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <span className="flex items-center gap-1.5 text-[11px] text-tea/70">
                <Train size={11} strokeWidth={1.5} />
                <span className="numeric">{activity.travelDuration} 分钟路程</span>
              </span>
              <span className="text-line/60">·</span>
              <span className="flex items-center gap-1.5 text-[11px] text-tea/70">
                <Clock size={11} strokeWidth={1.5} />
                <span className="numeric">
                  {formatDuration(activity.duration)}活动
                </span>
              </span>
            </div>
            <span className="text-[11px] text-cinnabar/70 font-medium">
              共 {activity.travelDuration * 2 + activity.duration} 分钟
            </span>
          </div>

          {/* 区域 + 价格行 */}
          <div className="flex items-center justify-between">
            <span className="flex items-center gap-1.5 text-[11px] text-tea/70">
              <MapPin size={11} strokeWidth={1.5} />
              {activity.region}区 · {activity.address.length > 8 ? activity.address.slice(0, 8) + "…" : activity.address}
            </span>
            <span className="flex items-center gap-1 text-[11px] text-tea/70">
              <Wallet size={11} strokeWidth={1.5} />
              {activity.price}
            </span>
          </div>
        </div>
      </div>
    </motion.button>
  );
}
