import { motion } from "framer-motion";
import { Heart, Footprints, Navigation } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useUserStore } from "@/store/useUserStore";

interface Props {
  activityId: string;
  coords: { lat: number; lng: number };
  name: string;
  address: string;
}

// 详情页底部行动区
export default function ActionBar({ activityId, coords, name, address }: Props) {
  const navigate = useNavigate();
  const { isLoggedIn, isFavorite, toggleFavorite, isVisited, toggleFootprint } = useUserStore();
  const fav = isFavorite(activityId);
  const visited = isVisited(activityId);

  // 未登录时跳转登录页，登录后返回详情页
  const guard = (action: () => void) => {
    if (!isLoggedIn) {
      navigate("/login", { state: { from: `/detail/${activityId}` } });
      return;
    }
    action();
  };

  // 外链到高德地图
  const goNavigate = () => {
    const url = `https://uri.amap.com/marker?position=${coords.lng},${coords.lat}&name=${encodeURIComponent(name)}&coordinate=wgs84&callnative=1`;
    window.open(url, "_blank");
  };

  return (
    <div className="border-t border-line/70 bg-paper/95 backdrop-blur-md px-4 py-3 pb-4">
      <div className="flex items-center gap-3">
        {/* 收藏 */}
        <button
          onClick={() => guard(() => toggleFavorite(activityId))}
          className="flex flex-col items-center gap-0.5 w-12"
          aria-label="收藏"
        >
          <motion.div
            animate={fav ? { scale: [1, 1.25, 0.95, 1] } : { scale: 1 }}
            transition={{ duration: 0.5 }}
          >
            <Heart
              size={20}
              strokeWidth={1.5}
              className={fav ? "fill-cinnabar text-cinnabar" : "text-ink/50"}
            />
          </motion.div>
          <span className={`text-[10px] ${fav ? "text-cinnabar" : "text-ink/40"}`}>
            收藏
          </span>
        </button>

        {/* 去过 */}
        <button
          onClick={() => guard(() => toggleFootprint(activityId))}
          className="flex flex-col items-center gap-0.5 w-12"
          aria-label="标记去过"
        >
          <motion.div
            animate={visited ? { scale: [1, 1.25, 0.95, 1] } : { scale: 1 }}
            transition={{ duration: 0.5 }}
          >
            <Footprints
              size={20}
              strokeWidth={1.5}
              className={
                visited ? "fill-cinnabar/20 text-cinnabar" : "text-ink/50"
              }
            />
          </motion.div>
          <span
            className={`text-[10px] ${visited ? "text-cinnabar" : "text-ink/40"}`}
          >
            去过
          </span>
        </button>

        {/* 导航出发 */}
        <button
          onClick={goNavigate}
          className="flex-1 ml-2 h-11 rounded-full bg-cinnabar text-cream text-sm tracking-wider flex items-center justify-center gap-2 shadow-sm hover:bg-cinnabar/90 transition-colors"
        >
          <Navigation size={15} strokeWidth={2} />
          导航出发
        </button>
      </div>
      <p className="mt-2 text-[10px] text-tea/50 text-center truncate">{address}</p>
    </div>
  );
}
