import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import { ArrowLeft, Check } from "lucide-react";
import StatusBar from "@/components/StatusBar";
import TagPill from "@/components/TagPill";
import { useUserStore } from "@/store/useUserStore";
import { CATEGORIES, REGIONS } from "@/types/activity";

export default function Preferences() {
  const navigate = useNavigate();
  const { preferences, toggleCategory, toggleRegion } = useUserStore();

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20, transition: { duration: 0.2 } }}
      className="flex-1 flex flex-col h-full"
    >
      <StatusBar />

      {/* 顶栏 */}
      <div className="flex items-center px-3 py-2">
        <button
          onClick={() => navigate("/profile")}
          className="w-9 h-9 flex items-center justify-center text-ink/70 hover:text-ink"
          aria-label="返回"
        >
          <ArrowLeft size={18} strokeWidth={1.5} />
        </button>
        <h1 className="font-serif text-base text-ink ml-1">偏好设置</h1>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar px-10 pb-8">
        {/* 兴趣标签 */}
        <section className="mb-8 mt-2">
          <h2 className="text-[11px] text-tea/60 tracking-wider mb-1">你感兴趣的事</h2>
          <p className="text-[11px] text-tea/40 mb-3">
            选几个你一个人也愿意去做的，会优先推荐
          </p>
          <div className="flex flex-wrap gap-2">
            {CATEGORIES.map((c) => (
              <TagPill
                key={c.key}
                label={c.label}
                active={preferences.categories.includes(c.key)}
                onClick={() => toggleCategory(c.key)}
              />
            ))}
          </div>
        </section>

        {/* 区域 */}
        <section className="mb-8">
          <h2 className="text-[11px] text-tea/60 tracking-wider mb-1">常去的区域</h2>
          <p className="text-[11px] text-tea/40 mb-3">
            不选也可以，全城都会出现
          </p>
          <div className="flex flex-wrap gap-2">
            {REGIONS.map((r) => (
              <TagPill
                key={r}
                label={r}
                active={preferences.regions.includes(r)}
                onClick={() => toggleRegion(r)}
              />
            ))}
          </div>
        </section>

        {/* 完成 */}
        <button
          onClick={() => navigate("/profile")}
          className="w-full h-11 rounded-full bg-cinnabar text-cream text-sm tracking-wider flex items-center justify-center gap-2 shadow-sm hover:bg-cinnabar/90 transition-colors"
        >
          <Check size={15} strokeWidth={2} />
          好了
        </button>

        <p className="text-center text-[10px] text-tea/40 font-serif italic mt-6">
          偏好只是参考，惊喜也在计划之外。
        </p>
      </div>
    </motion.div>
  );
}
