interface Props {
  label: string;
  active: boolean;
  onClick: () => void;
  size?: "sm" | "md";
}

export default function TagPill({ label, active, onClick, size = "md" }: Props) {
  const padding = size === "sm" ? "px-2.5 py-1 text-[11px]" : "px-3.5 py-1.5 text-xs";
  return (
    <button
      onClick={onClick}
      className={`${padding} rounded-full transition-all border ${
        active
          ? "bg-cinnabar/5 text-cinnabar border-cinnabar/40"
          : "bg-cream text-tea border-line hover:border-tea/40"
      }`}
    >
      {label}
    </button>
  );
}
