// 活动类别
export type Category =
  | "coffee"
  | "book"
  | "exhibition"
  | "walk"
  | "craft"
  | "film"
  | "park"
  | "market"
  | "tea"
  | "write"
  | "food"
  | "music";

// 建议时长（分钟），支持任意分钟数
export type Duration = number;

// 快捷预设时长
export const PRESET_DURATIONS: { value: Duration; label: string; short: string }[] = [
  { value: 15, label: "15 分钟", short: "15 min" },
  { value: 30, label: "30 分钟", short: "30 min" },
  { value: 60, label: "1 小时", short: "1 h" },
  { value: 120, label: "2 小时", short: "2 h" },
];

// 时段
export type DayPart = "morning" | "noon" | "afternoon" | "dusk" | "night";

export interface Activity {
  id: string;
  name: string;
  category: Category;
  duration: Duration; // 建议活动时长（分钟）
  travelDuration: Duration; // 单程路程时长（分钟），基于当前区域估算
  region: string; // 区域，如 "徐汇"
  address: string;
  hours: string; // 营业时间，如 "10:00–20:00"
  price: string; // 人均，如 "人均 ¥45"
  soloFriendly: 1 | 2 | 3; // 单人友好度，3 最高
  needBooking: boolean;
  tags: string[]; // 氛围标签
  cover: string; // 封面图
  images: string[]; // 详情氛围图
  oneLiner: string; // 卡片上的一句推荐语
  reason: string; // 详情页长文推荐理由
  coords: { lat: number; lng: number };
  // 时效性：限时活动（展览/市集/快闪）的结束日期，ISO 字符串
  // 缺省表示长期有效
  validUntil?: string;
}

// 判断活动是否已失效（已过 validUntil）
export function isExpired(activity: Activity, now: Date = new Date()): boolean {
  if (!activity.validUntil) return false;
  return new Date(activity.validUntil).getTime() < now.getTime();
}

// 分享记录
export interface ShareRecord {
  id: string;
  activityId: string;
  activityName: string; // 快照
  activityCover: string; // 快照
  region: string;
  authorName: string;
  authorAvatar: string; // 头像 URL 或字母
  rating: number; // 1-5
  comment: string;
  durationSpent: number; // 实际花费分钟数
  createdAt: string; // ISO
  mine?: boolean; // 是否是当前用户发布的（mock 数据用）
}

export interface CategoryMeta {
  key: Category;
  label: string;
  // 时段亲和权重
  affinity: Partial<Record<DayPart, number>>;
}

