// 时长格式化：小于60分钟显示分钟，否则显示小时
export function formatDuration(mins: number): string {
  if (mins < 60) return `${mins} 分钟`;
  if (mins === 60) return "1 小时";
  if (mins % 60 === 0) return `${Math.floor(mins / 60)} 小时`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${h} 小时 ${m} 分`;
}

// 时长简写：用于 segmented control
export function formatDurationShort(mins: number): string {
  if (mins < 60) return `${mins} min`;
  if (mins === 60) return "1 h";
  if (mins % 60 === 0) return `${Math.floor(mins / 60)} h`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${h}h ${m}m`;
}

