import { useEffect, useState } from "react";
import { ChevronDown, MapPin } from "lucide-react";
import { formatTime } from "@/lib/greeting";

// 模拟用户当前定位区域（真实场景由 LBS 提供）
export const LOCATED_REGION = "静安";

interface Props {
  region?: string | null; // 当前选中的区域，null = 全城
  locatedRegion?: string; // 模拟定位区域
  onRegionClick?: () => void;
}

// 模拟小程序顶部状态栏：左区域（可点击切换），右时间
export default function StatusBar({
  region = LOCATED_REGION,
  locatedRegion = LOCATED_REGION,
  onRegionClick,
}: Props) {
  const [time, setTime] = useState(formatTime());

  useEffect(() => {
    const t = setInterval(() => setTime(formatTime()), 30_000);
    return () => clearInterval(t);
  }, []);

  // 所有页面统一显示定位区域，与"发现"页一致
  const clickable = !!onRegionClick;
  const isLocated = region === locatedRegion;
  const label = region ? `${region}区` : "全城";

  return (
    <div className="flex items-center justify-between px-10 pt-12 pb-1 text-xs text-ink/70 font-sans">
      <button
        onClick={onRegionClick}
        disabled={!clickable}
        className={`flex items-center gap-1.5 ${
          clickable ? "hover:text-ink transition-colors" : "cursor-default"
        }`}
      >
        <MapPin
          size={12}
          strokeWidth={1.8}
          className={isLocated ? "text-cinnabar" : "text-tea/70"}
        />
        <span className="tracking-wider text-ink/80">{label}</span>
        <ChevronDown size={11} strokeWidth={1.8} className="text-tea/60" />
      </button>
      <div className="numeric text-sm text-ink/80">{time}</div>
    </div>
  );
}
