import { activities as ALL } from "@/data/activities";
import type { Activity, DayPart, Duration } from "@/types/activity";
import { CATEGORIES, isExpired } from "@/types/activity";

interface RecommendInput {
  duration: Duration;
  part: DayPart;
  preferences: { categories: string[]; regions: string[] };
  footprint: string[];
  seed?: number;
  limit?: number;
  region?: string | null; // 强过滤区域（来自顶部定位筛选），null/undefined = 全城
}

// 计算单个活动的推荐权重
function score(activity: Activity, input: RecommendInput): number {
  let s = 0;
  const meta = CATEGORIES.find((c) => c.key === activity.category);

  // 1. 时段亲和
  if (meta?.affinity?.[input.part]) {
    s += meta.affinity[input.part]!;
  }

  // 2. 偏好加权：类别
  if (input.preferences.categories.includes(activity.category)) {
    s += 2;
  }

  // 3. 偏好加权：区域
  if (input.preferences.regions.includes(activity.region)) {
    s += 1;
  }

  // 4. 单人友好度
  s += activity.soloFriendly * 0.3;

  // 5. 已去过降权（但保留）
  if (input.footprint.includes(activity.id)) {
    s -= 0.8;
  }

  return s;
}

// 简单的带 seed 洗牌
function shuffle<T>(arr: T[], seed: number): T[] {
  const a = [...arr];
  let s = seed;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 9301 + 49297) % 233280;
    const j = Math.floor((s / 233280) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function recommend(input: RecommendInput): Activity[] {
  const { duration, part, preferences, footprint, seed = Date.now(), limit = 6, region } = input;

  // 1. 时长过滤：总时长 = 路程*2（往返）+ 活动时长 <= 用户选择时长
  // 2. 区域强过滤：若指定 region，仅展示该区域活动
  // 3. 过期过滤：限时活动（展览/市集）过期后不再推荐
  const filtered = ALL.filter((a) => {
    const totalDuration = a.travelDuration * 2 + a.duration;
    if (totalDuration > duration) return false;
    if (region && a.region !== region) return false;
    if (isExpired(a)) return false;
    return true;
  });

  // 计算分数
  const scored = filtered.map((a) => ({
    activity: a,
    score: score(a, input),
  }));

  // 按分数降序
  scored.sort((x, y) => y.score - x.score);

  // 在分数相近的前 N*2 中随机洗牌，避免每次都一样的"最优"
  const top = scored.slice(0, Math.min(scored.length, limit * 2));
  const shuffled = shuffle(top, seed);

  return shuffled.slice(0, limit).map((x) => x.activity);
}
