import { motion } from "framer-motion";
import { PRESET_DURATIONS } from "@/types/activity";
import type { Duration } from "@/types/activity";
import { formatDurationShort } from "@/types/activity";

interface Props {
  value: Duration;
  onChange: (d: Duration) => void;
  onMore?: () => void; // 点击 "…" 打开自定义时长
}

// 分段控件：长胶囊白磨砂背景，居中，4个预设 + …
export default function DurationFilter({ value, onChange, onMore }: Props) {
  // 判断当前值是否是预设值之一
  const isPreset = PRESET_DURATIONS.some((d) => d.value === value);

  const allOptions = PRESET_DURATIONS.map((d) => ({
    value: d.value,
    label: d.short,
    isPreset: true,
  }));

  // 在位置 4 之后加 "…" 按钮
  // 实际渲染时将 "…" 作为最后一项
  const showMore = !!onMore;

  return (
    <div className="relative flex items-center w-full rounded-full bg-paper/70 backdrop-blur-lg border border-line/80 shadow-paper">
        {/* 选中态背景：运动的白色药片 */}
        {isPreset && (
          <motion.div
            layoutId="duration-pill"
            className="absolute top-1 bottom-1 rounded-full bg-cream shadow-md"
            style={{
              left: `calc((100% / (${allOptions.length}${showMore ? " + 1" : ""})) * ${allOptions.findIndex(
                (x) => x.value === value,
              )} + 4px)`,
              width: `calc(100% / (${allOptions.length}${showMore ? " + 1" : ""}) - 8px)`,
            }}
            transition={{ type: "spring", stiffness: 500, damping: 38 }}
          />
        )}

        {/* 预设选项 */}
        {allOptions.map((d) => {
          const active = d.value === value;
          return (
            <button
              key={d.value}
              onClick={() => onChange(d.value)}
              className={`relative z-10 flex-1 min-w-[52px] px-2.5 py-2 rounded-full text-xs whitespace-nowrap transition-colors ${
                active ? "text-ink font-medium" : "text-tea/70 hover:text-ink/70"
              }`}
            >
              {d.label}
            </button>
          );
        })}

        {/* … 按钮 */}
        {showMore && (
          <button
            onClick={onMore}
            className={`relative z-10 flex-1 min-w-[40px] px-2 py-2 rounded-full text-xs transition-colors ${
              !isPreset
                ? "text-ink font-medium"
                : "text-tea/70 hover:text-ink/70"
            }`}
          >
            …
          </button>
        )}
    </div>
  );
}
